  "claims": [
    {
      "claim": "Pidotimod, a small acidic amide/thioether with a single carboxylic acid and no basic amine, has human oral bioavailability of 42–44%, directly supporting that the query's polar acidic features can still yield F ≥ 20%.",
      "card_ids": ["C13", "C25"]
